using System;using UnityEngine;using Mojinloop.Data;using Mojinloop.Gameplay;
namespace Mojinloop.Combat { public sealed class CombatController:MonoBehaviour { [SerializeField] HeroStats heroStats;[SerializeField] GameplaySettings settings;[SerializeField] HeroController hero;[SerializeField] MonsterSpawner spawner;[SerializeField] Canvas canvas;[SerializeField] DamagePopup damagePrefab;[SerializeField] CoinDropEffect coinPrefab;float nextAttack,nextSpawn=-1;public int Coins{get;private set;}public event Action<int> CoinsChanged;public void Configure(HeroStats hs,GameplaySettings gs,HeroController h,MonsterSpawner s,Canvas c,DamagePopup d,CoinDropEffect coin){heroStats=hs;settings=gs;hero=h;spawner=s;canvas=c;damagePrefab=d;coinPrefab=coin;}void OnEnable(){if(spawner!=null)spawner.Spawned+=Bind;}void OnDisable(){if(spawner!=null)spawner.Spawned-=Bind;}void Bind(MonsterController m){m.Damaged+=OnDamaged;m.Died+=OnDied;}public void Tick(bool active,bool paused){var monster=spawner.Current;if(paused||!active||monster==null||monster.IsDead){if(hero.State!=HeroState.Dead)hero.SetState(HeroState.Idle);return;}float distance=monster.transform.position.x-hero.transform.position.x;if(distance>settings.attackRange){monster.Move(Time.unscaledDeltaTime);hero.SetState(HeroState.Running);}else{hero.SetState(HeroState.Attacking);if(Time.unscaledTime>=nextAttack){nextAttack=Time.unscaledTime+heroStats.attackInterval;monster.TakeDamage(heroStats.attackDamage);}}}void Update(){if(nextSpawn>0&&Time.unscaledTime>=nextSpawn){nextSpawn=-1;spawner.Spawn();}}void OnDamaged(MonsterController m,int damage){var p=Instantiate(damagePrefab);p.Show(damage,m.transform.position,canvas);}void OnDied(MonsterController m){m.Damaged-=OnDamaged;m.Died-=OnDied;Coins+=m.Data.coinReward;CoinsChanged?.Invoke(Coins);var c=Instantiate(coinPrefab);c.Play(m.Data.coinReward,m.transform.position,canvas);m.transform.localScale=Vector3.zero;nextSpawn=Time.unscaledTime+settings.nextSpawnDelay;} } }
